<script setup>
import {reactive,ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue';
import {Play,Pause,RotateCcw,Download,X,Film} from 'lucide-vue-next';
import {normalizeClip,clipTrack} from '../overlayAnimation.js';
import {appearanceRows} from '../appearances.js';
import {renderOverlayFrame} from '../overlayVideo.js';
import {animations} from '../motion.js';
const props=defineProps({studio:Object}),s=reactive(props.studio),root=ref(null),canvas=ref(null),time=ref(0),playing=ref(false),active=ref(null);
const rows=computed(()=>appearanceRows(s.banner.slide).filter(row=>row.keys.some(k=>!s.banner.slide.hiddenKeys?.includes(k)))),clip=computed(()=>normalizeClip(s.banner.clip,s.banner.slide.blockKeys)),chosen=computed(()=>rows.value.find(r=>r.id===active.value)),track=computed(()=>chosen.value?clipTrack(clip.value,chosen.value.keys[0],rows.value.indexOf(chosen.value)):null);
let raf,started,focus;
function draw(){if(canvas.value)renderOverlayFrame(canvas.value.getContext('2d'),s.banner.slide,s.theme,clip.value,time.value,canvas.value.width,canvas.value.height);}
function stop(){playing.value=false;cancelAnimationFrame(raf);}
function tick(now){time.value=Math.min(clip.value.duration,(now-started)/1000);draw();if(time.value>=clip.value.duration)stop();else raf=requestAnimationFrame(tick);}
function play(){if(playing.value){stop();return;}if(time.value>=clip.value.duration)time.value=0;started=performance.now()-time.value*1000;playing.value=true;raf=requestAnimationFrame(tick);}
function global(field,value){s.banner.clip={...clip.value,[field]:value};s.banner.clip=normalizeClip(s.banner.clip,s.banner.slide.blockKeys);time.value=Math.min(time.value,clip.value.duration);}
function number(field,event,perBlock=false,commit=false){const raw=event.target.value,n=Number(raw),min=field==='duration'?2:field==='start'||field==='stagger'?0:.1,max=field==='duration'?20:field==='stagger'?.5:field==='start'?clip.value.duration-.1:field==='end'?clip.value.duration:3;if(raw===''||!Number.isFinite(n))return;if(!commit&&(n<min||n>max))return;(perBlock?patch:global)(field,n);if(commit)event.target.value=String(Math.max(min,Math.min(max,n)));}
function patch(field,value){if(!chosen.value)return;const tracks={...clip.value.tracks};for(const key of chosen.value.keys)tracks[key]={...track.value,[field]:value};s.banner.clip=normalizeClip({...clip.value,tracks},s.banner.slide.blockKeys);}
function close(){if(s.overlayVideoBusy)return;stop();s.overlayVideoOpen=false;}
function seek(event){stop();time.value=Number(event.target.value);}
function keyboard(event){if(event.key==='Escape'){event.preventDefault();close();}if(event.key!=='Tab')return;const controls=[...root.value.querySelectorAll('button,input,select,a[href]')].filter(el=>!el.disabled&&el.getClientRects().length),first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
watch([time,clip,()=>s.banner.slide,()=>s.theme],draw,{deep:true,flush:'post'});watch(()=>s.overlayVideoBusy,busy=>{if(busy)stop();});
onMounted(async()=>{focus=document.activeElement;await nextTick();active.value=rows.value.find(row=>row.keys.some(key=>s.selectedKeys.includes(key)))?.id||null;root.value.querySelector('button')?.focus();draw();});onUnmounted(()=>{stop();focus?.focus?.();});
</script>
<template><Teleport to="body"><div class="modal-backdrop" @pointerdown.stop @keydown.stop="keyboard" @click.self="close"><section ref="root" class="overlay-video-dialog" role="dialog" aria-modal="true" aria-label="Animer l’incrustation"><header class="overlay-video-heading"><div><span class="eyebrow"><Film :size="14"/> INCRUSTATION ANIMÉE</span><h2>Une entrée. Une sortie. Ton rythme.</h2></div><button class="icon-btn" :disabled="s.overlayVideoBusy" aria-label="Fermer l’animation" @click="close"><X :size="20"/></button></header><div class="overlay-video-body"><div class="overlay-video-preview"><div class="overlay-video-screen"><canvas ref="canvas" width="960" height="540" role="img" aria-label="Aperçu animé de l’incrustation"/></div><div class="overlay-video-transport"><button class="icon-btn" :disabled="s.overlayVideoBusy" :aria-label="playing?'Pause de l’aperçu':'Lire l’aperçu'" @click="play"><Pause v-if="playing" :size="17"/><Play v-else :size="17"/></button><button class="icon-btn" aria-label="Revenir au début" @click="stop();time=0"><RotateCcw :size="16"/></button><input type="range" min="0" :max="clip.duration" step=".01" :value="time" aria-label="Position de l’aperçu en secondes" @input="seek"><output>{{time.toFixed(2)}} / {{clip.duration.toFixed(1)}} s</output></div><fieldset :disabled="s.overlayVideoBusy" class="overlay-clip-options"><label>Durée<input type="number" :value="clip.duration" min="2" max="20" step=".1" aria-label="Durée de l’incrustation en secondes" @input="number('duration',$event)" @change="number('duration',$event,false,true)"><small>2 à 20 secondes · 30 images/s</small></label><label>Export<select :value="clip.background" aria-label="Fond de la vidéo" @change="global('background',$event.target.value)"><option value="transparent">Transparent · MOV sans perte</option><option value="chroma">Fond de chrominance · WebM</option></select></label><label v-if="clip.background==='chroma'">Fond à retirer au montage<div class="clip-chroma"><input type="color" :value="clip.chroma" aria-label="Couleur du fond de chrominance" @input="global('chroma',$event.target.value)"><button class="btn" @click="global('chroma','#00ff00')">Vert</button><button class="btn" @click="global('chroma','#0000ff')">Bleu</button></div></label></fieldset><p class="field-help">{{clip.background==='transparent'?'MOV avec canal alpha, images PNG sans perte. Plus volumineux ; certains logiciels nécessitent une conversion vers ProRes 4444. L’aperçu ci-dessus est le rendu de l’animation.':'WebM enregistré en temps réel. Reste sur cet onglet pendant l’export ; choisis une couleur absente de tes objets pour la retirer au montage.'}}</p><div v-if="s.lastExport?.name.startsWith('frame-incrustation-')" class="clip-export-ready"><strong>Vidéo prête · {{s.lastExport.size}} Ko</strong><a class="btn" :href="s.lastExport.url" :download="s.lastExport.name"><Download :size="15"/>{{s.lastExport.name}}</a></div></div><div class="overlay-video-settings"><fieldset :disabled="s.overlayVideoBusy"><legend>Rythme par défaut</legend><div class="clip-field-grid"><label>Entrée<select :value="clip.animation" aria-label="Entrée par défaut" @change="global('animation',$event.target.value)"><option v-for="[id,label] in animations" :key="id" :value="id">{{label}}</option></select></label><label>Sortie<select :value="clip.exitAnimation" aria-label="Sortie par défaut" @change="global('exitAnimation',$event.target.value)"><option v-for="[id,label] in animations" :key="id" :value="id">{{label}}</option></select></label><label>Durée d’entrée · s<input type="number" :value="clip.entry" min=".1" max="3" step=".1" aria-label="Durée d’entrée par défaut" @input="number('entry',$event)" @change="number('entry',$event,false,true)"></label><label>Durée de sortie · s<input type="number" :value="clip.exit" min=".1" max="3" step=".1" aria-label="Durée de sortie par défaut" @input="number('exit',$event)" @change="number('exit',$event,false,true)"></label><label>Décalage entre blocs · s<input type="number" :value="clip.stagger" min="0" max=".5" step=".02" aria-label="Décalage entre blocs" @input="number('stagger',$event)" @change="number('stagger',$event,false,true)"></label></div><div class="clip-object-heading"><strong>Blocs et groupes</strong><button class="btn" @click="s.banner.clip.tracks={}">Tout réinitialiser</button></div><p class="field-help">Les membres d’un groupe restent synchronisés. Les réglages de la présentation ne sont pas modifiés.</p><div class="clip-object-list"><button v-for="(row,n) in rows" :key="row.id" :class="['clip-object-row',{active:active===row.id}]" :aria-pressed="active===row.id" @click="active=active===row.id?null:row.id"><span><strong>{{row.label}}</strong><small>{{row.keys.length>1?row.members:''}}</small></span><span>{{clipTrack(clip,row.keys[0],n).start.toFixed(2)}} → {{clipTrack(clip,row.keys[0],n).end.toFixed(2)}} s</span></button></div><div v-if="chosen" class="clip-track-settings"><strong>{{chosen.label}}</strong><div class="clip-field-grid"><label>Arrivée · s<input type="number" :value="track.start" min="0" :max="clip.duration-.1" step=".1" aria-label="Arrivée du bloc" @input="number('start',$event,true)" @change="number('start',$event,true,true)"></label><label>Fin de sortie · s<input type="number" :value="track.end" :min="track.start+.1" :max="clip.duration" step=".1" aria-label="Fin de sortie du bloc" @input="number('end',$event,true)" @change="number('end',$event,true,true)"></label><label>Entrée<select :value="track.animation" aria-label="Animation d’entrée du bloc" @change="patch('animation',$event.target.value)"><option v-for="[id,label] in animations" :key="id" :value="id">{{label}}</option></select></label><label>Sortie<select :value="track.exitAnimation" aria-label="Animation de sortie du bloc" @change="patch('exitAnimation',$event.target.value)"><option v-for="[id,label] in animations" :key="id" :value="id">{{label}}</option></select></label><label>Durée d’entrée · s<input type="number" :value="track.entry" min=".1" max="3" step=".1" aria-label="Durée d’entrée du bloc" @input="number('entry',$event,true)" @change="number('entry',$event,true,true)"></label><label>Durée de sortie · s<input type="number" :value="track.exit" min=".1" max="3" step=".1" aria-label="Durée de sortie du bloc" @input="number('exit',$event,true)" @change="number('exit',$event,true,true)"></label></div></div></fieldset></div></div><footer class="overlay-video-footer"><template v-if="s.overlayVideoBusy"><span role="status">Création de la vidéo · {{s.overlayVideoProgress}} %</span><progress :value="s.overlayVideoProgress" max="100" aria-label="Progression de l’export vidéo"/><button class="btn" @click="s.cancelOverlayVideo()">Annuler l’export</button></template><template v-else><span>{{s.resolution.width}} × {{s.resolution.height}} · {{clip.duration}} s · sans audio</span><button class="btn primary" @click="s.exportOverlayVideo()"><Download :size="16"/>Exporter la vidéo</button></template></footer></section></div></Teleport></template>
